import {PRIZES,stars,equipped,equip} from './prizes.js';
function apply(){document.body.dataset.look=equipped().id;}
apply();const root=document.getElementById('prizeShop');
function render(){if(!root)return;root.replaceChildren();const total=stars(),current=equipped(),next=PRIZES.find(p=>p.stars>total),heading=document.createElement('h2'),note=document.createElement('p'),grid=document.createElement('div');heading.textContent='スターで着せ替え！';note.textContent='★ '+total+' ／ '+(next?'次の「'+next.name+'」まで '+(next.stars-total)+' 個':'すべての着せ替えを解放！');grid.className='prize-grid';for(const p of PRIZES){const b=document.createElement('button'),art=document.createElement('span'),name=document.createElement('strong'),status=document.createElement('small');art.className='prize-driver';art.style.backgroundPosition=(p.driver%3)*50+'% '+Math.floor(p.driver/3)*100+'%';name.textContent=p.name;const locked=p.stars>total;status.textContent=locked?'★ '+p.stars+' で解放':current.id===p.id?'使用中':'着せ替える';b.disabled=locked;b.setAttribute('aria-pressed',String(p.id===current.id));b.append(art,name,status);b.onclick=()=>{if(equip(p.id)){apply();render();}else note.textContent='保存できませんでした。ブラウザの保存設定を確認してください。';};grid.append(b);}root.append(heading,note,grid);const help=document.createElement('p');help.textContent='カートの自分のキャラと、ゲーム画面の色が変わります。スターは減りません。記録はこのブラウザ内に保存。';root.append(help);}
render();window.addEventListener('storage',()=>{apply();render();});
